<script setup lang="ts">import { ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useSessionStore } from '../stores/session'; const username=ref('');const password=ref('');const isLoading=ref(false);const router=useRouter();const route=useRoute();const session=useSessionStore(); async function login(){isLoading.value=true;try{session.setSession('demo-session',['knowledge:write','feedback:read','analytics:read','users:write']);await router.push(String(route.query.redirect||'/'))}finally{isLoading.value=false}};</script>
<template><h1>欢迎回来</h1><p class="muted">登录知识库问答系统</p><el-form @submit.prevent="login"><el-form-item label="账号"><el-input v-model="username" autocomplete="username" /></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" show-password autocomplete="current-password" /></el-form-item><el-button native-type="submit" type="primary" :loading="isLoading" style="width:100%">登录</el-button></el-form></template>
